package io.kimpton.slayerblocklists;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.io.UnsupportedEncodingException;
import java.net.URLEncoder;
import java.util.List;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.util.LinkBrowser;

/** One collapsible master card: a clickable header (name, blocked/unlocked
 *  count, chevron) over a body of slot rows. The card is created once and
 *  updated in place, so its expand state and the panel's scroll survive the
 *  per-tick refreshes. The player's assigning master is accented and shown as
 *  "on task". */
class MasterSection extends JPanel
{
	private static final String WIKI_SEARCH = "https://oldschool.runescape.wiki/w/Special:Search?search=";
	private static final Color BLOCKED_DOT = new Color(220, 90, 90);

	private final String master;
	private final JPanel header = new JPanel(new BorderLayout());
	private final JLabel chevron = new JLabel("▸"); // right-pointing triangle
	private final JLabel nameLabel = new JLabel();
	private final JLabel countLabel = new JLabel();
	private final JPanel body = new JPanel();

	private boolean expanded;
	private boolean everPopulated;

	MasterSection(String master)
	{
		this.master = master;
		setLayout(new BorderLayout());
		setAlignmentX(Component.LEFT_ALIGNMENT);
		setBackground(ColorScheme.DARKER_GRAY_COLOR);
		setBorder(BorderFactory.createEmptyBorder(0, 0, 4, 0)); // gap between cards

		header.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		header.setBorder(BorderFactory.createEmptyBorder(6, 8, 6, 8));
		header.setCursor(new Cursor(Cursor.HAND_CURSOR));

		chevron.setFont(FontManager.getRunescapeSmallFont());
		chevron.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		chevron.setBorder(BorderFactory.createEmptyBorder(0, 0, 0, 6));

		nameLabel.setFont(FontManager.getRunescapeBoldFont());
		nameLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);

		JPanel left = new JPanel(new BorderLayout());
		left.setOpaque(false);
		left.add(chevron, BorderLayout.WEST);
		left.add(nameLabel, BorderLayout.CENTER);

		countLabel.setFont(FontManager.getRunescapeSmallFont());
		countLabel.setForeground(ColorScheme.MEDIUM_GRAY_COLOR);
		countLabel.setHorizontalAlignment(SwingConstants.RIGHT);

		header.add(left, BorderLayout.CENTER);
		header.add(countLabel, BorderLayout.EAST);

		body.setLayout(new BoxLayout(body, BoxLayout.Y_AXIS));
		body.setBackground(ColorScheme.DARK_GRAY_COLOR);
		body.setBorder(BorderFactory.createEmptyBorder(4, 10, 6, 8));
		body.setVisible(false);

		header.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				setExpanded(!expanded);
			}

			@Override
			public void mouseEntered(MouseEvent e)
			{
				header.setBackground(ColorScheme.DARKER_GRAY_HOVER_COLOR);
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				header.setBackground(ColorScheme.DARKER_GRAY_COLOR);
			}
		});

		add(header, BorderLayout.NORTH);
		add(body, BorderLayout.CENTER);
	}

	/** Repopulates the card from the model. Called on the EDT for each master. */
	void update(SlayerData.Model m, List<SlayerData.Model.Slot> slots)
	{
		boolean active = master.equals(m.activeMaster);

		int blocked = 0;
		int unlocked = 0;
		for (SlayerData.Model.Slot s : slots)
		{
			if (s.blocked)
			{
				blocked++;
			}
			if (isUnlocked(s, m))
			{
				unlocked++;
			}
		}

		nameLabel.setText(active ? master + "  • on task" : master);
		nameLabel.setForeground(active ? ColorScheme.BRAND_ORANGE : ColorScheme.LIGHT_GRAY_COLOR);
		// Full = all available slots used (green), else muted.
		countLabel.setText(blocked + "/" + unlocked);
		countLabel.setForeground(unlocked > 0 && blocked >= unlocked
			? ColorScheme.PROGRESS_COMPLETE_COLOR : ColorScheme.MEDIUM_GRAY_COLOR);

		body.removeAll();
		for (SlayerData.Model.Slot slot : slots)
		{
			addSlotRow(m, slot);
		}

		// Auto-expand the active master the first time we have data; afterwards
		// respect whatever the user toggled.
		if (!everPopulated)
		{
			everPopulated = true;
			setExpanded(active);
		}

		body.revalidate();
		body.repaint();
	}

	private boolean isUnlocked(SlayerData.Model.Slot s, SlayerData.Model m)
	{
		if (s.blocked)
		{
			return true;
		}
		if (s.slot == 0)
		{
			return m.diaryDone;
		}
		return m.questPoints >= s.slot * 50;
	}

	private void addSlotRow(SlayerData.Model m, SlayerData.Model.Slot slot)
	{
		if (slot.blocked)
		{
			String name = slot.name != null ? slot.name : "Task #" + slot.taskId;
			body.add(creatureRow(name));
			return;
		}
		if (slot.slot == 0)
		{
			if (!m.diaryDone)
			{
				if (m.showLockedSlots)
				{
					body.add(note("🔒 Diary slot - Elite Lumbridge & Draynor"));
				}
			}
			else if (m.showEmptySlots)
			{
				body.add(note("Diary slot - empty"));
			}
			return;
		}
		int need = slot.slot * 50;
		if (m.questPoints < need)
		{
			if (m.showLockedSlots)
			{
				body.add(note("🔒 Slot " + slot.slot + " - " + need + " QP"));
			}
		}
		else if (m.showEmptySlots)
		{
			body.add(note("Slot " + slot.slot + " - empty"));
		}
	}

	/** A blocked creature: a colored bullet + a wiki-linked button. */
	private JPanel creatureRow(String name)
	{
		JPanel row = new JPanel(new BorderLayout());
		row.setOpaque(false);
		row.setAlignmentX(Component.LEFT_ALIGNMENT);

		JLabel dot = new JLabel("•");
		dot.setForeground(BLOCKED_DOT);
		dot.setFont(FontManager.getRunescapeFont());
		dot.setBorder(BorderFactory.createEmptyBorder(0, 0, 0, 6));
		dot.setVerticalAlignment(SwingConstants.TOP);

		JButton link = new JButton("<html>" + name + "</html>");
		link.setFont(FontManager.getRunescapeFont());
		link.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		link.setToolTipText("Open " + name + " on the OSRS Wiki");
		link.setCursor(new Cursor(Cursor.HAND_CURSOR));
		link.setBorder(BorderFactory.createEmptyBorder(1, 0, 1, 0));
		link.setContentAreaFilled(false);
		link.setFocusPainted(false);
		link.setHorizontalAlignment(SwingConstants.LEFT);
		link.addActionListener(e -> LinkBrowser.browse(wikiSearchUrl(name)));

		row.add(dot, BorderLayout.WEST);
		row.add(link, BorderLayout.CENTER);
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, row.getPreferredSize().height));
		return row;
	}

	private JLabel note(String text)
	{
		JLabel l = new JLabel("<html>" + text + "</html>");
		l.setFont(FontManager.getRunescapeFont());
		l.setForeground(ColorScheme.MEDIUM_GRAY_COLOR);
		l.setAlignmentX(Component.LEFT_ALIGNMENT);
		l.setBorder(BorderFactory.createEmptyBorder(1, 0, 1, 0));
		return l;
	}

	private void setExpanded(boolean expand)
	{
		expanded = expand;
		chevron.setText(expand ? "▾" : "▸"); // down / right triangle
		body.setVisible(expand);
		revalidate();
		repaint();
	}

	private static String wikiSearchUrl(String name)
	{
		try
		{
			return WIKI_SEARCH + URLEncoder.encode(name, "UTF-8");
		}
		catch (UnsupportedEncodingException e)
		{
			return WIKI_SEARCH + name.replace(' ', '+');
		}
	}
}

package io.kimpton.slayerblocklists;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(SlayerBlockListsConfig.GROUP)
public interface SlayerBlockListsConfig extends Config
{
	String GROUP = "slayerblocklists";

	@ConfigItem(
		keyName = "showCurrentTask",
		name = "Current task",
		description = "<p width='250'>Show your current slayer task at the top of the panel.</p>",
		position = 0
	)
	default boolean showCurrentTask()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showLockedSlots",
		name = "Locked slots",
		description = "<p width='250'>Show locked block slots with what unlocks them (quest points per slot; Elite Lumbridge & Draynor diary for the seventh).</p>",
		position = 1
	)
	default boolean showLockedSlots()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showEmptySlots",
		name = "Empty slots",
		description = "<p width='250'>Show unlocked block slots that have nothing blocked yet.</p>",
		position = 2
	)
	default boolean showEmptySlots()
	{
		return true;
	}
}

package io.kimpton.slayerblocklists;

import java.awt.BorderLayout;
import java.awt.Component;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.awt.Rectangle;
import java.io.UnsupportedEncodingException;
import java.net.URLEncoder;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.ImageIcon;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.Scrollable;
import javax.swing.SwingConstants;
import javax.swing.SwingUtilities;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.util.ImageUtil;
import net.runelite.client.util.LinkBrowser;

/** The Slayer Block Lists side panel. A prominent current-task card and
 *  points/streak chips sit above a stack of collapsible per-master cards; the
 *  master who gave your current task is accented and auto-expanded. Persistent
 *  components are updated in place so expand state and scroll position survive
 *  each tick's refresh. Text wraps; the panel only ever scrolls vertically. */
class SlayerBlockListsPanel extends PluginPanel
{
	private static final String COFFEE_URL = "https://buymeacoffee.com/kimpton";
	private static final String WIKI_SEARCH = "https://oldschool.runescape.wiki/w/Special:Search?search=";

	private final JScrollPane scroll;

	// Waiting-for-login placeholder, swapped out once real data arrives.
	private final JLabel placeholder = new JLabel("Log in to load your slayer block lists.");
	private final JPanel data = column(); // everything below the header

	// Current-task card.
	private final JPanel taskCard = new JPanel(new BorderLayout());
	private final JButton taskLine = linkButton("");
	private final JLabel taskSub = subtle("");
	private final JLabel taskArea = subtle("");

	// Stat chips.
	private final JLabel pointsValue = statValue();
	private final JLabel streakValue = statValue();

	// One card per master, created once and updated in place.
	private final Map<String, MasterSection> sections = new LinkedHashMap<>();

	SlayerBlockListsPanel()
	{
		super(false);
		setLayout(new BorderLayout());
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		JPanel content = column();
		content.setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));
		content.setBackground(ColorScheme.DARK_GRAY_COLOR);

		content.add(buildHeader());
		content.add(Box.createVerticalStrut(10));

		placeholder.setFont(FontManager.getRunescapeFont());
		placeholder.setForeground(ColorScheme.MEDIUM_GRAY_COLOR);
		placeholder.setAlignmentX(Component.LEFT_ALIGNMENT);
		content.add(placeholder);

		buildTaskCard();
		data.add(taskCard);
		data.add(Box.createVerticalStrut(8));
		data.add(buildStatChips());
		data.add(Box.createVerticalStrut(10));
		data.add(sectionTitle("Block lists"));
		for (String master : SlayerData.MASTER_NAMES)
		{
			MasterSection s = new MasterSection(master);
			sections.put(master, s);
			data.add(s);
		}
		data.setVisible(false);
		content.add(data);

		// Vertical-only scrolling: the wrapper tracks the viewport width so long
		// text wraps instead of pushing content (and the coffee button) off-screen.
		ScrollableColumn north = new ScrollableColumn();
		north.add(content, BorderLayout.NORTH);
		scroll = new JScrollPane(north,
			JScrollPane.VERTICAL_SCROLLBAR_AS_NEEDED, JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);
		scroll.setBorder(null);
		scroll.getVerticalScrollBar().setUnitIncrement(16);
		add(scroll, BorderLayout.CENTER);
	}

	private JPanel buildHeader()
	{
		JPanel header = new JPanel(new BorderLayout());
		header.setOpaque(false);
		header.setAlignmentX(Component.LEFT_ALIGNMENT);
		JLabel title = new JLabel("Slayer Block Lists");
		title.setFont(FontManager.getRunescapeBoldFont());
		title.setForeground(ColorScheme.BRAND_ORANGE);
		header.add(title, BorderLayout.WEST);
		JButton coffee = new JButton(new ImageIcon(ImageUtil.loadImageResource(SlayerBlockListsPanel.class, "coffee.png")));
		coffee.setToolTipText("Enjoying the plugin? Buy me a coffee");
		coffee.setCursor(new Cursor(Cursor.HAND_CURSOR));
		coffee.setBorder(BorderFactory.createEmptyBorder(2, 2, 2, 2));
		coffee.setContentAreaFilled(false);
		coffee.setFocusPainted(false);
		coffee.addActionListener(e -> LinkBrowser.browse(COFFEE_URL));
		header.add(coffee, BorderLayout.EAST);
		return header;
	}

	private void buildTaskCard()
	{
		taskCard.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		taskCard.setBorder(BorderFactory.createEmptyBorder(8, 10, 8, 10));
		taskCard.setAlignmentX(Component.LEFT_ALIGNMENT);

		JPanel col = column();
		JLabel caption = new JLabel("CURRENT TASK");
		caption.setFont(FontManager.getRunescapeSmallFont());
		caption.setForeground(ColorScheme.BRAND_ORANGE);
		caption.setAlignmentX(Component.LEFT_ALIGNMENT);

		taskLine.setFont(FontManager.getRunescapeBoldFont());
		taskLine.setForeground(ColorScheme.TEXT_COLOR);
		taskLine.setMaximumSize(new Dimension(Integer.MAX_VALUE, Integer.MAX_VALUE));

		col.add(caption);
		col.add(Box.createVerticalStrut(2));
		col.add(taskLine);
		col.add(taskSub);
		col.add(taskArea);
		taskCard.add(col, BorderLayout.CENTER);
	}

	private JPanel buildStatChips()
	{
		JPanel row = new JPanel(new GridLayout(1, 2, 6, 0));
		row.setOpaque(false);
		row.setAlignmentX(Component.LEFT_ALIGNMENT);
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 48));
		row.add(chip(pointsValue, "points"));
		row.add(chip(streakValue, "streak"));
		return row;
	}

	private JPanel chip(JLabel value, String caption)
	{
		JPanel chip = new JPanel(new BorderLayout());
		chip.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		chip.setBorder(BorderFactory.createEmptyBorder(6, 8, 6, 8));
		JLabel cap = new JLabel(caption, SwingConstants.CENTER);
		cap.setFont(FontManager.getRunescapeSmallFont());
		cap.setForeground(ColorScheme.MEDIUM_GRAY_COLOR);
		chip.add(value, BorderLayout.CENTER);
		chip.add(cap, BorderLayout.SOUTH);
		return chip;
	}

	/** Called on the EDT whenever the underlying vars changed. Updates in place,
	 *  preserving scroll position and each card's expand state. */
	void update(SlayerData.Model m)
	{
		final int pos = scroll.getVerticalScrollBar().getValue();

		placeholder.setVisible(false);
		data.setVisible(true);

		taskCard.setVisible(m.showCurrentTask);
		if (m.showCurrentTask)
		{
			if (m.task != null)
			{
				String name = m.task.name != null ? m.task.name : "Task";
				taskLine.setText("<html>" + m.task.remaining + "x " + name + "</html>");
				taskLine.setToolTipText("Open " + name + " on the OSRS Wiki");
				String url = wikiSearchUrl(name);
				for (java.awt.event.ActionListener al : taskLine.getActionListeners())
				{
					taskLine.removeActionListener(al);
				}
				taskLine.addActionListener(e -> LinkBrowser.browse(url));
				taskLine.setEnabled(true);

				taskSub.setText(m.task.master != null ? "Assigned by " + m.task.master : "");
				taskSub.setVisible(m.task.master != null);
				taskArea.setText(m.task.area != null ? "<html>Must kill in: " + m.task.area + "</html>" : "");
				taskArea.setVisible(m.task.area != null);
			}
			else
			{
				taskLine.setText("No active task");
				taskLine.setToolTipText(null);
				taskLine.setEnabled(false);
				for (java.awt.event.ActionListener al : taskLine.getActionListeners())
				{
					taskLine.removeActionListener(al);
				}
				taskSub.setVisible(false);
				taskArea.setVisible(false);
			}
		}

		pointsValue.setText(String.format("%,d", m.points));
		streakValue.setText(String.format("%,d", m.streak));

		for (Map.Entry<String, List<SlayerData.Model.Slot>> e : m.masters.entrySet())
		{
			MasterSection s = sections.get(e.getKey());
			if (s != null)
			{
				s.update(m, e.getValue());
			}
		}

		revalidate();
		repaint();
		SwingUtilities.invokeLater(() -> scroll.getVerticalScrollBar().setValue(pos));
	}

	// ---- small builders ----

	private static JButton linkButton(String text)
	{
		JButton b = new JButton(text);
		b.setFont(FontManager.getRunescapeFont());
		b.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		b.setCursor(new Cursor(Cursor.HAND_CURSOR));
		b.setBorder(BorderFactory.createEmptyBorder(1, 0, 1, 0));
		b.setContentAreaFilled(false);
		b.setFocusPainted(false);
		b.setHorizontalAlignment(SwingConstants.LEFT);
		b.setAlignmentX(Component.LEFT_ALIGNMENT);
		return b;
	}

	private static JLabel subtle(String text)
	{
		JLabel l = new JLabel(text);
		l.setFont(FontManager.getRunescapeSmallFont());
		l.setForeground(ColorScheme.MEDIUM_GRAY_COLOR);
		l.setAlignmentX(Component.LEFT_ALIGNMENT);
		return l;
	}

	private static JLabel statValue()
	{
		JLabel l = new JLabel("-", SwingConstants.CENTER);
		l.setFont(FontManager.getRunescapeBoldFont());
		l.setForeground(ColorScheme.BRAND_ORANGE);
		return l;
	}

	private static JLabel sectionTitle(String text)
	{
		JLabel l = new JLabel(text.toUpperCase());
		l.setFont(FontManager.getRunescapeSmallFont());
		l.setForeground(ColorScheme.MEDIUM_GRAY_COLOR);
		l.setBorder(BorderFactory.createEmptyBorder(0, 0, 4, 0));
		l.setAlignmentX(Component.LEFT_ALIGNMENT);
		return l;
	}

	private static JPanel column()
	{
		JPanel p = new JPanel();
		p.setLayout(new BoxLayout(p, BoxLayout.Y_AXIS));
		p.setOpaque(false);
		p.setAlignmentX(Component.LEFT_ALIGNMENT);
		return p;
	}

	private static String wikiSearchUrl(String name)
	{
		try
		{
			return WIKI_SEARCH + URLEncoder.encode(name, "UTF-8");
		}
		catch (UnsupportedEncodingException e)
		{
			return WIKI_SEARCH + name.replace(' ', '+');
		}
	}

	/** BorderLayout panel that always matches the scroll viewport's width, so
	 *  content can only grow downward (vertical scrolling, wrapped text). */
	private static class ScrollableColumn extends JPanel implements Scrollable
	{
		ScrollableColumn()
		{
			super(new BorderLayout());
			setBackground(ColorScheme.DARK_GRAY_COLOR);
		}

		@Override
		public Dimension getPreferredScrollableViewportSize()
		{
			return getPreferredSize();
		}

		@Override
		public int getScrollableUnitIncrement(Rectangle visibleRect, int orientation, int direction)
		{
			return 16;
		}

		@Override
		public int getScrollableBlockIncrement(Rectangle visibleRect, int orientation, int direction)
		{
			return 64;
		}

		@Override
		public boolean getScrollableTracksViewportWidth()
		{
			return true;
		}

		@Override
		public boolean getScrollableTracksViewportHeight()
		{
			return false;
		}
	}
}

package io.kimpton.slayerblocklists;

import com.google.inject.Provides;
import java.util.Arrays;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.GameTick;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;

@Slf4j
@PluginDescriptor(
	name = "Slayer Block Lists",
	description = "Shows your slayer block list for every master: blocked creatures as wiki links, plus empty and locked slots with their unlock requirements.",
	tags = {"slayer", "block", "blocklist", "task", "master", "konar", "duradel", "nieve", "krystilia"}
)
public class SlayerBlockListsPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private SlayerBlockListsConfig config;

	@Inject
	private SlayerData slayerData;

	private SlayerBlockListsPanel panel;
	private NavigationButton navButton;

	// Change detection: the raw var values behind everything the panel shows.
	// Rebuilding only when one changes keeps the per-tick cost to varbit reads.
	private int[] lastFingerprint;

	@Provides
	SlayerBlockListsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(SlayerBlockListsConfig.class);
	}

	@Override
	protected void startUp()
	{
		panel = new SlayerBlockListsPanel();
		navButton = NavigationButton.builder()
			.tooltip("Slayer Block Lists")
			.icon(ImageUtil.loadImageResource(getClass(), "panel_icon.png"))
			.priority(6)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);
		lastFingerprint = null;
	}

	@Override
	protected void shutDown()
	{
		if (navButton != null)
		{
			clientToolbar.removeNavigation(navButton);
			navButton = null;
			panel = null;
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (SlayerBlockListsConfig.GROUP.equals(event.getGroup()))
		{
			lastFingerprint = null; // re-render with the new settings next tick
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (client.getGameState() != GameState.LOGGED_IN || panel == null)
		{
			return;
		}
		int[] fp = fingerprint();
		if (Arrays.equals(fp, lastFingerprint))
		{
			return;
		}
		// Collect on the client thread (varbits + cache DB lookups), render on the EDT.
		SlayerData.Model model = slayerData.collect(config);
		if (model.namesPending)
		{
			// A creature name didn't resolve yet (cache tables still loading);
			// leave the fingerprint stale so next tick retries the lookup.
			lastFingerprint = null;
		}
		else
		{
			lastFingerprint = fp;
		}
		final SlayerBlockListsPanel p = panel;
		SwingUtilities.invokeLater(() -> p.update(model));
	}

	/** Every var the panel renders, in one comparable array. */
	private int[] fingerprint()
	{
		int[] fp = new int[SlayerData.BLOCK_VARBITS_TOTAL + 8];
		int i = SlayerData.fillBlockVarbits(client, fp);
		fp[i++] = client.getVarpValue(VarPlayerID.QP);
		fp[i++] = client.getVarbitValue(VarbitID.LUMBRIDGE_DIARY_ELITE_COMPLETE);
		fp[i++] = client.getVarpValue(VarPlayerID.SLAYER_TARGET);
		fp[i++] = client.getVarpValue(VarPlayerID.SLAYER_COUNT);
		fp[i++] = client.getVarpValue(VarPlayerID.SLAYER_AREA);
		fp[i++] = client.getVarbitValue(VarbitID.SLAYER_MASTER);
		fp[i++] = client.getVarbitValue(VarbitID.SLAYER_POINTS);
		fp[i] = client.getVarbitValue(VarbitID.SLAYER_TASKS_COMPLETED);
		return fp;
	}
}

package io.kimpton.slayerblocklists;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.gameval.DBTableID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;

/** Reads the slayer block lists, current task and gating state from the client
 *  (client thread only) into an immutable model the panel renders on the EDT.
 *  Creature names resolve via the SlayerTask DB table with a bundled
 *  game-cache mapping as fallback. */
@Slf4j
@Singleton
class SlayerData
{
	/** One master's block varbits: six purchasable slots then the diary slot. */
	private static final int[][] MASTER_VARBITS = {
		{VarbitID.SLAYER_BLOCKED_TURAEL_1, VarbitID.SLAYER_BLOCKED_TURAEL_2, VarbitID.SLAYER_BLOCKED_TURAEL_3,
			VarbitID.SLAYER_BLOCKED_TURAEL_4, VarbitID.SLAYER_BLOCKED_TURAEL_5, VarbitID.SLAYER_BLOCKED_TURAEL_6,
			VarbitID.SLAYER_BLOCKED_TURAEL_DIARY},
		{VarbitID.SLAYER_BLOCKED_MAZCHNA_1, VarbitID.SLAYER_BLOCKED_MAZCHNA_2, VarbitID.SLAYER_BLOCKED_MAZCHNA_3,
			VarbitID.SLAYER_BLOCKED_MAZCHNA_4, VarbitID.SLAYER_BLOCKED_MAZCHNA_5, VarbitID.SLAYER_BLOCKED_MAZCHNA_6,
			VarbitID.SLAYER_BLOCKED_MAZCHNA_DIARY},
		{VarbitID.SLAYER_BLOCKED_VANNAKA_1, VarbitID.SLAYER_BLOCKED_VANNAKA_2, VarbitID.SLAYER_BLOCKED_VANNAKA_3,
			VarbitID.SLAYER_BLOCKED_VANNAKA_4, VarbitID.SLAYER_BLOCKED_VANNAKA_5, VarbitID.SLAYER_BLOCKED_VANNAKA_6,
			VarbitID.SLAYER_BLOCKED_VANNAKA_DIARY},
		{VarbitID.SLAYER_BLOCKED_CHAELDAR_1, VarbitID.SLAYER_BLOCKED_CHAELDAR_2, VarbitID.SLAYER_BLOCKED_CHAELDAR_3,
			VarbitID.SLAYER_BLOCKED_CHAELDAR_4, VarbitID.SLAYER_BLOCKED_CHAELDAR_5, VarbitID.SLAYER_BLOCKED_CHAELDAR_6,
			VarbitID.SLAYER_BLOCKED_CHAELDAR_DIARY},
		{VarbitID.SLAYER_BLOCKED_KONAR_1, VarbitID.SLAYER_BLOCKED_KONAR_2, VarbitID.SLAYER_BLOCKED_KONAR_3,
			VarbitID.SLAYER_BLOCKED_KONAR_4, VarbitID.SLAYER_BLOCKED_KONAR_5, VarbitID.SLAYER_BLOCKED_KONAR_6,
			VarbitID.SLAYER_BLOCKED_KONAR_DIARY},
		{VarbitID.SLAYER_BLOCKED_NIEVE_1, VarbitID.SLAYER_BLOCKED_NIEVE_2, VarbitID.SLAYER_BLOCKED_NIEVE_3,
			VarbitID.SLAYER_BLOCKED_NIEVE_4, VarbitID.SLAYER_BLOCKED_NIEVE_5, VarbitID.SLAYER_BLOCKED_NIEVE_6,
			VarbitID.SLAYER_BLOCKED_NIEVE_DIARY},
		{VarbitID.SLAYER_BLOCKED_DURADEL_1, VarbitID.SLAYER_BLOCKED_DURADEL_2, VarbitID.SLAYER_BLOCKED_DURADEL_3,
			VarbitID.SLAYER_BLOCKED_DURADEL_4, VarbitID.SLAYER_BLOCKED_DURADEL_5, VarbitID.SLAYER_BLOCKED_DURADEL_6,
			VarbitID.SLAYER_BLOCKED_DURADEL_DIARY},
		{VarbitID.SLAYER_BLOCKED_KRYSTILIA_1, VarbitID.SLAYER_BLOCKED_KRYSTILIA_2, VarbitID.SLAYER_BLOCKED_KRYSTILIA_3,
			VarbitID.SLAYER_BLOCKED_KRYSTILIA_4, VarbitID.SLAYER_BLOCKED_KRYSTILIA_5, VarbitID.SLAYER_BLOCKED_KRYSTILIA_6,
			VarbitID.SLAYER_BLOCKED_KRYSTILIA_DIARY},
	};

	static final String[] MASTER_NAMES = {
		"Turael", "Mazchna", "Vannaka", "Chaeldar", "Konar", "Nieve", "Duradel", "Krystilia",
	};

	static final int BLOCK_VARBITS_TOTAL = 8 * 7;

	// SLAYER_MASTER varbit value -> assigning master. 0 = no master assigned.
	// Ordered by when each master was added to the game, NOT by combat level: the
	// four originals then Duradel(5), then Nieve(6)/Krystilia(7)/Konar(8).
	private static final String[] ASSIGNING_MASTER = {
		null, "Turael", "Mazchna", "Vannaka", "Chaeldar", "Duradel", "Nieve", "Krystilia", "Konar quo Maten",
	};

	// SLAYER_MASTER varbit value -> block-list display key (matches MASTER_NAMES).
	private static final String[] MASTER_KEY_BY_ID = {
		null, "Turael", "Mazchna", "Vannaka", "Chaeldar", "Duradel", "Nieve", "Krystilia", "Konar",
	};

	@Inject
	private Client client;

	// DB-table lookups are stable per session; failed (null) lookups are NOT
	// cached so they retry once the cache tables are available.
	private final Map<Integer, String> taskNameCache = new HashMap<>();
	private final Map<Integer, String> areaNameCache = new HashMap<>();

	/** Immutable render model. */
	static class Model
	{
		int points;
		int streak;
		int questPoints;
		boolean diaryDone;
		boolean showCurrentTask;
		boolean showLockedSlots;
		boolean showEmptySlots;
		Task task; // null = no active task
		String activeMaster; // display key of the master who gave the current task (null = none)
		// master display name -> 7 slots (slot 1..6 then the diary slot, slot=0)
		final Map<String, List<Slot>> masters = new LinkedHashMap<>();
		boolean namesPending;

		static class Task
		{
			String name;
			int remaining;
			String master;
			String area;
		}

		static class Slot
		{
			int slot; // 1..6, 0 = diary slot
			boolean blocked;
			int taskId;
			String name; // null when unresolvable
		}
	}

	/** Fills the block varbit values into fp starting at 0; returns the next index. */
	static int fillBlockVarbits(Client client, int[] fp)
	{
		int i = 0;
		for (int[] master : MASTER_VARBITS)
		{
			for (int vb : master)
			{
				fp[i++] = client.getVarbitValue(vb);
			}
		}
		return i;
	}

	Model collect(SlayerBlockListsConfig config)
	{
		Model m = new Model();
		m.points = client.getVarbitValue(VarbitID.SLAYER_POINTS);
		m.streak = client.getVarbitValue(VarbitID.SLAYER_TASKS_COMPLETED);
		m.questPoints = client.getVarpValue(VarPlayerID.QP);
		m.diaryDone = client.getVarbitValue(VarbitID.LUMBRIDGE_DIARY_ELITE_COMPLETE) > 0;
		m.showCurrentTask = config.showCurrentTask();
		m.showLockedSlots = config.showLockedSlots();
		m.showEmptySlots = config.showEmptySlots();

		int taskId = client.getVarpValue(VarPlayerID.SLAYER_TARGET);
		int remaining = client.getVarpValue(VarPlayerID.SLAYER_COUNT);
		if (taskId > 0 && remaining > 0)
		{
			Model.Task t = new Model.Task();
			t.name = taskName(taskId);
			t.remaining = remaining;
			int masterId = client.getVarbitValue(VarbitID.SLAYER_MASTER);
			t.master = masterId > 0 && masterId < ASSIGNING_MASTER.length ? ASSIGNING_MASTER[masterId] : null;
			m.activeMaster = masterId > 0 && masterId < MASTER_KEY_BY_ID.length ? MASTER_KEY_BY_ID[masterId] : null;
			t.area = areaName(client.getVarpValue(VarPlayerID.SLAYER_AREA));
			m.task = t;
			if (t.name == null)
			{
				m.namesPending = true;
			}
		}

		for (int mi = 0; mi < MASTER_VARBITS.length; mi++)
		{
			List<Model.Slot> slots = new ArrayList<>(7);
			for (int si = 0; si < MASTER_VARBITS[mi].length; si++)
			{
				Model.Slot slot = new Model.Slot();
				slot.slot = si < 6 ? si + 1 : 0;
				slot.taskId = client.getVarbitValue(MASTER_VARBITS[mi][si]);
				slot.blocked = slot.taskId > 0;
				if (slot.blocked)
				{
					slot.name = taskName(slot.taskId);
					if (slot.name == null)
					{
						m.namesPending = true;
					}
				}
				slots.add(slot);
			}
			m.masters.put(MASTER_NAMES[mi], slots);
		}
		return m;
	}

	/** Resolves a slayer_task DB id to its creature name: session cache, then the
	 *  live DB table, then the bundled game-cache mapping. Null if unknown. */
	private String taskName(int taskId)
	{
		if (taskId <= 0)
		{
			return null;
		}
		String name = taskNameCache.get(taskId);
		if (name != null)
		{
			return name;
		}
		name = lookupTaskName(taskId);
		if (name == null)
		{
			name = SlayerTaskNames.name(taskId);
		}
		if (name != null)
		{
			taskNameCache.put(taskId, name);
		}
		return name;
	}

	private String lookupTaskName(int taskId)
	{
		try
		{
			List<Integer> rows = client.getDBRowsByValue(DBTableID.SlayerTask.ID, DBTableID.SlayerTask.COL_ID, 0, taskId);
			if (rows == null || rows.isEmpty())
			{
				return null;
			}
			Object[] nameField = client.getDBTableField(rows.get(0), DBTableID.SlayerTask.COL_NAME_UPPERCASE, 0);
			if (nameField == null || nameField.length == 0 || nameField[0] == null)
			{
				return null;
			}
			return String.valueOf(nameField[0]);
		}
		catch (Exception e)
		{
			log.debug("Could not resolve slayer task name for id {}", taskId, e);
			return null;
		}
	}

	/** Konar's location-locked task area (the name the slayer helper shows). */
	private String areaName(int areaId)
	{
		if (areaId <= 0)
		{
			return null;
		}
		String name = areaNameCache.get(areaId);
		if (name != null)
		{
			return name;
		}
		try
		{
			List<Integer> rows = client.getDBRowsByValue(DBTableID.SlayerArea.ID, DBTableID.SlayerArea.COL_AREA_ID, 0, areaId);
			if (rows == null || rows.isEmpty())
			{
				return null;
			}
			Object[] nameField = client.getDBTableField(rows.get(0), DBTableID.SlayerArea.COL_AREA_NAME_IN_HELPER, 0);
			if (nameField == null || nameField.length == 0 || nameField[0] == null)
			{
				return null;
			}
			name = String.valueOf(nameField[0]);
			areaNameCache.put(areaId, name);
			return name;
		}
		catch (Exception e)
		{
			log.debug("Could not resolve slayer area name for id {}", areaId, e);
			return null;
		}
	}
}

package io.kimpton.slayerblocklists;

import java.io.IOException;
import java.io.InputStream;
import java.util.Properties;

/** Bundled slayer task id → name mapping (dumped from the game cache's
 *  slayer_task DB table). Fallback for when the live DB lookup yields nothing
 *  (the cache tables load lazily). */
final class SlayerTaskNames
{
	private static final Properties NAMES = load();

	private SlayerTaskNames()
	{
	}

	static String name(int taskId)
	{
		return taskId > 0 ? NAMES.getProperty(String.valueOf(taskId)) : null;
	}

	private static Properties load()
	{
		Properties p = new Properties();
		try (InputStream in = SlayerTaskNames.class.getResourceAsStream(
			"/io/kimpton/slayerblocklists/slayer-task-names.properties"))
		{
			if (in != null)
			{
				p.load(in);
			}
		}
		catch (IOException e)
		{
			// Names then resolve to null; consumers fall back to task ids.
		}
		return p;
	}
}

